#!/usr/bin/env node
'use strict';

const path = require('node:path');
const { TodoError, loadTodos, addTodo, completeTodo, deleteTodo } = require('./todos');

const TODOS_FILE = 'todos.json';

const USAGE = `Usage: node index.js <command> [arguments]

Commands:
  add <text>      Add a new todo
  list            List all todos
  complete <id>   Mark a todo as done
  delete <id>     Delete a todo
  help            Show this help message`;

function parseId(command, args) {
  if (args.length === 0) {
    throw new TodoError(`Missing todo id. Usage: node index.js ${command} <id>`);
  }
  if (args.length > 1) {
    throw new TodoError(`Expected a single todo id, got ${args.length} arguments`);
  }

  const [value] = args;
  const id = Number(value);
  if (!/^\d+$/.test(value) || id < 1 || !Number.isSafeInteger(id)) {
    throw new TodoError(`Invalid todo id "${value}": must be a positive integer`);
  }
  return id;
}

function formatTodos(todos) {
  const width = String(Math.max(...todos.map((t) => t.id))).length;
  return todos
    .map((t) => `${String(t.id).padStart(width)}. [${t.completed ? 'x' : ' '}] ${t.text}`)
    .join('\n');
}

// Runs a command and returns the process exit code.
function main(argv) {
  const file = path.join(process.cwd(), TODOS_FILE);
  const [command, ...args] = argv;

  switch (command) {
    case 'add': {
      const text = args.join(' ');
      if (text.trim() === '') {
        throw new TodoError('Missing todo text. Usage: node index.js add "<text>"');
      }
      const todo = addTodo(file, text);
      console.log(`Added todo #${todo.id}: ${todo.text}`);
      return 0;
    }

    case 'list': {
      const todos = loadTodos(file);
      console.log(
        todos.length === 0 ? 'No todos yet. Add one with: node index.js add "<text>"' : formatTodos(todos)
      );
      return 0;
    }

    case 'complete': {
      const { todo, changed } = completeTodo(file, parseId(command, args));
      console.log(
        changed
          ? `Completed todo #${todo.id}: ${todo.text}`
          : `Todo #${todo.id} is already completed: ${todo.text}`
      );
      return 0;
    }

    case 'delete': {
      const todo = deleteTodo(file, parseId(command, args));
      console.log(`Deleted todo #${todo.id}: ${todo.text}`);
      return 0;
    }

    case 'help':
    case '--help':
    case '-h':
      console.log(USAGE);
      return 0;

    case undefined:
      console.error(USAGE);
      return 1;

    default:
      console.error(`Error: Unknown command "${command}"\n\n${USAGE}`);
      return 1;
  }
}

try {
  process.exitCode = main(process.argv.slice(2));
} catch (err) {
  console.error(`Error: ${err.message}`);
  process.exitCode = 1;
}
